rules:
--surface: var(--spd-p-bg);
--line: var(--spd-p-border);
--text-muted: var(--spd-p-text-muted);
--primary: var(--spd-p-primary);
--primary-strong: var(--spd-p-primary-strong);
--accent: var(--spd-p-warning);
--danger: var(--spd-p-danger);
--focus: var(--spd-p-focus);
--medical-mint: var(--spd-p-primary-soft);
--medical-aqua: var(--spd-p-code-chip-bg);
--medical-warm: var(--spd-p-warning-bg);
--medical-warm-strong: var(--spd-p-warning);
--tech-blue: var(--spd-p-info);
--saas-bg: var(--spd-p-bg-page);
--saas-surface-muted: var(--spd-p-neutral-surface);
--saas-heading: var(--spd-p-text-strong);
--saas-success: var(--spd-p-success);

border-right-color: var(--spd-p-border);
background: var(--spd-p-bg);
box-shadow: var(--spd-p-shadow-1);

border-color: var(--spd-p-primary-border);
color: var(--primary);
background: var(--spd-p-primary-bg);

color: var(--spd-p-primary-strong);
background: var(--spd-p-primary-bg);
box-shadow: inset 3px 0 var(--spd-p-primary);

border: 1px solid #e5eaf0;
border-radius: 12px;
background: rgba(255, 255, 255, 0.96);
box-shadow: 0 2px 8px rgba(31, 50, 79, 0.04);

border: 1px solid var(--spd-p-border);
border-radius: 12px;
background: color-mix(in srgb, var(--spd-p-bg) 96%, transparent);
box-shadow: var(--spd-p-shadow-1);

border: 1px solid var(--spd-p-border) !important;
border-radius: 12px;
background: linear-gradient(115deg, var(--spd-p-bg) 0%, var(--spd-p-bg) 76%, var(--spd-p-primary-soft) 100%) !important;

border: 1px solid #e5eaf0 !important;
border-radius: 12px;
background: #ffffff !important;
box-shadow: 0 2px 8px rgba(31, 50, 79, 0.035) !important;

border: 1px solid var(--spd-p-border) !important;
border-radius: 12px;
background: var(--spd-p-bg) !important;
box-shadow: var(--spd-p-shadow-1) !important;

border-color: var(--spd-p-border) !important;
color: var(--spd-p-text);
background-color: var(--spd-p-bg);

border-color: var(--spd-p-border);
color: var(--spd-p-text);
background: var(--spd-p-bg);

border-color: var(--spd-p-primary-border);
color: var(--primary);
background: var(--spd-p-primary-bg);

border: 1px solid var(--spd-p-border);
border-radius: 10px;
background: var(--spd-p-bg);

border-bottom-color: var(--spd-p-border) !important;
color: var(--spd-p-text-secondary) !important;
background: var(--spd-p-row-header-bg) !important;

color: var(--spd-p-success-text) !important;
background: var(--spd-p-success-bg) !important;
border-color: var(--spd-p-success-border) !important;

color: var(--spd-p-primary-text) !important;
background: var(--spd-p-primary-bg) !important;
border-color: var(--spd-p-primary-border) !important;

color: var(--spd-p-text-secondary) !important;
background: var(--spd-p-neutral-surface) !important;
border-color: var(--spd-p-border) !important;

color: var(--spd-p-warning-text) !important;
background: var(--spd-p-warning-bg) !important;
border-color: var(--spd-p-warning-border) !important;

color: var(--spd-p-danger-text) !important;
background: var(--spd-p-danger-bg) !important;
border-color: var(--spd-p-danger-border) !important;

border: 1px solid #e3e8ef !important;
border-radius: 14px;
background: #ffffff !important;
box-shadow: 0 16px 48px rgba(23, 32, 51, 0.14) !important;

border: 1px solid var(--spd-p-border) !important;
border-radius: 14px;
background: var(--spd-p-bg) !important;
box-shadow: var(--spd-p-shadow-dialog) !important;
